<h2 class="text-2xl font-semibold text-[#6d0205]">Nuestro Canal</h2>
<div class="container">
    <!-- Reproductor de video -->
    <div class="video-player">
        <iframe
            width="100%"
            height="100%"
            src={`https://www.youtube.com/embed/${selectedVideo.id}`}
            title={selectedVideo.title}
            frameborder="0"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowfullscreen
        ></iframe>
        <h2>{selectedVideo.title}</h2>
    </div>

    <!-- Lista de videos en grilla -->
    <div class="video-list">
        <div class="grid">
            {#each videos as video}
                <div
                    class="video-thumbnail"
                    role="button"
                    tabindex="0"
                    on:click={() => selectVideo(video)}
                    on:keydown={(e) => {
                        if (e.key === "Enter") selectVideo(video);
                    }}
                >
                    <img src={video.thumbnail} alt={video.title} />
                    <p>{video.title}</p>
                </div>
            {/each}
        </div>
    </div>
</div>

<style>
    .container {
        display: flex;
        height: auto; /* Ocupa toda la altura de la pantalla */
    }

    .video-player,
    .video-list {
        width: 50%;
        height: 550px;
        padding: 10px;
        box-sizing: border-box;
    }

    .video-player {
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    .video-list {
        overflow-y: auto; /* Scroll vertical */
    }

    .grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr); /* 3 columnas */
        grid-gap: 10px;
    }

    .video-thumbnail {
        cursor: pointer;
        text-align: center;
    }

    .video-thumbnail img {
        width: 80%;
        height: auto;
        border-radius: 8px;
    }

    .video-thumbnail p {
        margin-top: 8px;
        font-size: 14px;
    }

    @media (max-width: 768px) {
        .container {
            flex-direction: column;
        }

        .video-player,
        .video-list {
            width: 100%;
            height: 50%; /* Ocupa 50% de la pantalla */
        }
    }
</style>
