<script>
    import { createEventDispatcher } from "svelte";
    const dispatch = createEventDispatcher();

    export let menuItems = [];

    function handleClick(item) {
        console.log("🚀 ~ handleClick ~ item:", item)
        dispatch("click", item);
    }

</script>

<nav class="w-full  lg:w-48 bg-gray-800 p-2 text-white">
    <ul>
        {#each menuItems as item}
            {#if typeof item === "string"}
                <!-- svelte-ignore a11y-click-events-have-key-events -->
                <li class="py-1 border-b border-gray-600 hover:bg-gray-700 cursor-pointer text-sm lg:text-base" on:click={handleClick(item)}>
                    {item}
                </li>
            {:else}
                <li class="py-1 border-b border-gray-600 hover:bg-gray-700 cursor-pointer text-sm lg:text-base">
                    {item.title}
                    <ul class="ml-2 mt-1 text-xs lg:text-sm">
                        {#each item.submenu as subitem}
                            <!-- svelte-ignore a11y-click-events-have-key-events -->
                            <li class="py-1 hover:bg-gray-600 cursor-pointer" on:click={handleClick(subitem) }>
                                {subitem}
                            </li>
                        {/each}
                    </ul>
                </li>
            {/if}
        {/each}
    </ul>
</nav>
