<script>
  import { onMount, onDestroy } from 'svelte';
 import {link} from 'svelte-spa-router'

  let isOpen = false;
  let isScrolled = false;

  function toggleMenu() {
    isOpen = !isOpen;
  }

  function handleScroll() {
    // Cambia a true si se ha desplazado más de 50px
    isScrolled = window.scrollY > 50;
  }

  // Añade un listener de scroll cuando el componente se monta
  onMount(() => {
    window.addEventListener('scroll', handleScroll);
  });

  // Limpia el listener cuando el componente se desmonta
  onDestroy(() => {
    window.removeEventListener('scroll', handleScroll);
  });
</script>

<nav class={`bg-[#d7d7d7] text-white py-4 ${isScrolled ? 'fixed top-0 left-0 w-full shadow-lg' : ''} transition-all duration-300`}>
